class Solution {
public:
    vector<int> findErrorNums(vector<int>& nums) {
        int duplicate = -1, missing = -1;
        for (int n : nums) {
            int val = abs(n);
            if (nums[val - 1] < 0) {
                duplicate = val;
            } else {
                nums[val - 1] = -nums[val - 1];
            }
        }
        for (int i = 0; i < (int)nums.size(); i++) {
            if (nums[i] > 0) {
                missing = i + 1;
                break;
            }
        }
        return {duplicate, missing};
    }
};

