        for (int n : nums) {
            int val = Math.abs(n);
            if (nums[val - 1] < 0) {
                duplicate = val;
            } else {
                nums[val - 1] = -nums[val - 1];
            }
        }
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] > 0) {
                missing = i + 1;
                break;
            }
        }
        return new int[]{duplicate, missing};
    }
}

